mapper.select:
SELECT id, session_id, sender_id, sender_role, type, content,
       client_msg_id, reply_to_message_id, create_time, original_content, recalled, recalled_at
FROM chat_message
WHERE session_id = #{sessionId}
  AND sender_id = #{senderId}
  AND client_msg_id = #{clientMsgId}
LIMIT 1

mapper.update:
UPDATE chat_message
SET recalled = 1,
    recalled_at = #{recalledAt}
WHERE id = #{messageId}
  AND sender_id = #{senderId}
  AND recalled = 0
  AND create_time >= #{cutoffTime}

mapper.select:
SELECT id, session_id, sender_id, sender_role, type, content, client_msg_id, reply_to_message_id, create_time, original_content, recalled, recalled_at FROM ( SELECT id, session_id, sender_id, sender_role, type, content, client_msg_id, reply_to_message_id, create_time, original_content, recalled, recalled_at, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY create_time DESC, id DESC) AS row_num FROM chat_message WHERE session_id IN
#{sessionId}
) latest WHERE row_num = 1
